-- Holcim Event System - Supabase/PostgreSQL foundation (Phase 1), part 2/3.
-- Translation of the MySQL schema after migrations 001-032, reviewed table by
-- table. Logical schema, names and relationships are kept so data can be
-- imported 1:1 with the SAME ids. Translation rules (see docs/SUPABASE_MIGRATION.md):
--   AUTO_INCREMENT      -> "generated by default as identity" (explicit ids allowed
--                          on import; sequences are moved past the old values after import)
--   UNSIGNED            -> integer/bigint/smallint + CHECK (>= 0) where it matters
--   ENUM                -> text + CHECK (easier to extend than enum types)
--   JSON (longtext)     -> jsonb
--   DATETIME (Manila)   -> timestamptz (import reads each value as Asia/Manila)
--   ON UPDATE CURRENT_TIMESTAMP -> trigger public.set_updated_at()
--   generated active_lock + UNIQUE -> partial unique index (same guarantee)
--   utf8mb4_unicode_ci uniqueness  -> unique index on lower(col) (case-insensitive
--                          like MySQL). Plain text comparisons are case-sensitive in
--                          PostgreSQL; later phases must use ILIKE / lower() for search.
--   ascii_bin token     -> text COLLATE "C" (exact, case-sensitive, byte order)
--   MySQL FK without ON DELETE  -> ON DELETE RESTRICT (MySQL default)
-- MySQL's schema_migrations table is not copied (Supabase tracks its own migrations);
-- the import records the source migration list in migration_import_runs.

-- ---------------------------------------------------------------- users
-- Legacy application accounts. Kept for ids referenced by history (drawn_by,
-- scanner_user_id, audit_logs.user_id...) and for the Phase 3 Auth migration.
-- password_hash = PHP password_hash() bcrypt. RLS + revoked grants (part 3) keep it private.
create table public.users (
  id              integer generated by default as identity primary key,
  name            varchar(150) not null,
  email           varchar(190),
  username        varchar(60),
  password_hash   varchar(255) not null,
  session_version integer not null default 0 check (session_version >= 0),
  role            text not null default 'event_operator'
                  check (role in ('admin', 'registration_staff', 'event_operator', 'scanner_operator')),
  status          text not null default 'active' check (status in ('active', 'inactive')),
  last_login_at   timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create unique index uq_users_email on public.users (lower(email));
create unique index uq_users_username on public.users (lower(username));
create index idx_users_role on public.users (role);
create index idx_users_status on public.users (status);

-- ---------------------------------------------------------------- events
create table public.events (
  id          integer generated by default as identity primary key,
  name        varchar(200) not null,
  description text,
  event_date  date not null,
  status      text not null default 'draft' check (status in ('draft', 'active', 'completed', 'archived')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
-- MySQL: generated active_lock = IF(status='active',1,NULL) + UNIQUE -> at most one active event.
create unique index uq_events_single_active on public.events ((true)) where status = 'active';
create index idx_events_status on public.events (status);
create index idx_events_event_date on public.events (event_date);

-- ---------------------------------------------------------------- event_days
create table public.event_days (
  id          integer generated by default as identity primary key,
  event_id    integer not null references public.events (id) on delete restrict,
  day_number  smallint not null check (day_number >= 0),
  event_date  date not null,
  label       varchar(100),
  status      text not null default 'upcoming' check (status in ('upcoming', 'active', 'completed')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint uq_event_days_event_number unique (event_id, day_number),
  constraint uq_event_days_id_event unique (id, event_id)
);
-- MySQL: generated active_lock = IF(status='active',event_id,NULL) + UNIQUE -> one current day per event.
create unique index uq_event_days_one_active on public.event_days (event_id) where status = 'active';

-- ---------------------------------------------------------------- import_batches
create table public.import_batches (
  id                integer generated by default as identity primary key,
  event_id          integer not null references public.events (id) on delete restrict on update cascade,
  event_day_id      integer references public.event_days (id) on delete set null on update cascade,
  import_type       text not null check (import_type in ('attendees', 'major_entries')),
  original_filename varchar(255) not null,
  status            text not null default 'pending' check (status in ('pending', 'processing', 'completed', 'failed')),
  total_rows        integer not null default 0 check (total_rows >= 0),
  successful_rows   integer not null default 0 check (successful_rows >= 0),
  failed_rows       integer not null default 0 check (failed_rows >= 0),
  column_mapping    jsonb,
  error_summary     jsonb,
  imported_by       integer references public.users (id) on delete set null on update cascade,
  created_at        timestamptz not null default now(),
  completed_at      timestamptz
);
create index idx_import_batches_event_type on public.import_batches (event_id, import_type);
create index idx_import_batches_imported_by on public.import_batches (imported_by);
create index idx_import_batches_day on public.import_batches (event_day_id);

-- ---------------------------------------------------------------- attendees
create table public.attendees (
  id                  integer generated by default as identity primary key,
  event_id            integer not null references public.events (id) on delete restrict on update cascade,
  attendee_code       varchar(64) not null,
  full_name           varchar(200) not null,
  company             varchar(200),
  department          varchar(150),          -- business label: Cluster (location / region)
  email               varchar(190),
  external_identifier varchar(190),          -- business label: Employee ID
  status              text not null default 'active' check (status in ('active', 'archived')),
  archived_at         timestamptz,
  extra_data          jsonb,
  import_batch_id     integer references public.import_batches (id) on delete set null on update cascade,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint uq_attendees_id_event unique (id, event_id)   -- target of composite FKs
);
-- MySQL utf8mb4_unicode_ci made these case-insensitive.
create unique index uq_attendees_event_code on public.attendees (event_id, lower(attendee_code));
create unique index uq_attendees_event_external on public.attendees (event_id, lower(external_identifier));
create index idx_attendees_event_name on public.attendees (event_id, full_name);
create index idx_attendees_event_department on public.attendees (event_id, department);
create index idx_attendees_event_email on public.attendees (event_id, email);
create index idx_attendees_import_batch on public.attendees (import_batch_id);
create index idx_attendees_event_status on public.attendees (event_id, status);
create index idx_attendees_event_company on public.attendees (event_id, company);

-- ---------------------------------------------------------------- attendee_qr_codes
-- CRITICAL: the token is the printed QR payload. Stored exactly as issued:
-- text COLLATE "C" (byte-exact, case-sensitive; "-" and "_" significant).
-- The CHECK is the set the registration scanner accepts; it never alters data,
-- it only refuses a value that could not be scanned (e.g. surrounding spaces).
create table public.attendee_qr_codes (
  id          integer generated by default as identity primary key,
  attendee_id integer not null references public.attendees (id) on delete cascade on update cascade,
  token       text collate "C" not null check (token ~ '^[A-Za-z0-9_-]{16,64}$'),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint uq_attendee_qr_codes_token unique (token),
  constraint uq_attendee_qr_codes_attendee unique (attendee_id)   -- one QR per attendee
);

-- ---------------------------------------------------------------- registration_scans
create table public.registration_scans (
  id              integer generated by default as identity primary key,
  event_id        integer not null references public.events (id) on delete restrict on update cascade,
  event_day_id    integer not null,
  attendee_id     integer not null,
  qr_code_id      integer references public.attendee_qr_codes (id) on delete set null on update cascade,
  scanner_user_id integer references public.users (id) on delete set null on update cascade,
  scanned_at      timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  constraint uq_registration_scans_day_attendee unique (event_day_id, attendee_id),   -- one check-in per day
  constraint fk_registration_scans_attendee_event foreign key (attendee_id, event_id)
    references public.attendees (id, event_id) on delete cascade on update cascade,
  constraint fk_registration_scans_day_event foreign key (event_day_id, event_id)
    references public.event_days (id, event_id) on delete restrict on update cascade
);
create index idx_registration_scans_attendee_event on public.registration_scans (attendee_id, event_id);
create index idx_registration_scans_event_time on public.registration_scans (event_id, scanned_at);
create index idx_registration_scans_scanner on public.registration_scans (scanner_user_id);
create index idx_registration_scans_qr_code on public.registration_scans (qr_code_id);
create index idx_registration_scans_day_time on public.registration_scans (event_day_id, scanned_at);
create index idx_registration_scans_day_scanner on public.registration_scans (event_day_id, scanner_user_id);
create index fk_registration_scans_day_event on public.registration_scans (event_day_id, event_id);

-- ---------------------------------------------------------------- scan_logs
create table public.scan_logs (
  id           bigint generated by default as identity primary key,
  event_id     integer not null,
  event_day_id integer not null,
  user_id      integer references public.users (id) on delete set null on update cascade,
  attendee_id  integer references public.attendees (id) on delete set null on update cascade,
  result       text not null check (result in ('registered', 'already_registered', 'invalid_qr', 'wrong_event', 'attendee_inactive')),
  scanned_at   timestamptz not null default now(),
  constraint fk_scan_logs_day_event foreign key (event_day_id, event_id)
    references public.event_days (id, event_id) on delete restrict on update cascade
);
create index idx_scan_logs_day_time on public.scan_logs (event_day_id, scanned_at);
create index idx_scan_logs_day_user_time on public.scan_logs (event_day_id, user_id, scanned_at);
create index idx_scan_logs_day_result on public.scan_logs (event_day_id, result);
create index idx_scan_logs_user on public.scan_logs (user_id);
create index idx_scan_logs_attendee on public.scan_logs (attendee_id);
create index idx_scan_logs_event on public.scan_logs (event_id);
create index fk_scan_logs_day_event on public.scan_logs (event_day_id, event_id);

-- ---------------------------------------------------------------- minor_manual_entries
create table public.minor_manual_entries (
  id           integer generated by default as identity primary key,
  event_id     integer not null,
  event_day_id integer not null,
  attendee_id  integer not null,
  added_by     integer references public.users (id) on delete set null on update cascade,
  reason       varchar(200),
  created_at   timestamptz not null default now(),
  constraint uq_minor_manual_day_attendee unique (event_day_id, attendee_id),
  constraint fk_minor_manual_attendee_event foreign key (attendee_id, event_id)
    references public.attendees (id, event_id) on delete restrict on update cascade,
  constraint fk_minor_manual_day_event foreign key (event_day_id, event_id)
    references public.event_days (id, event_id) on delete restrict on update cascade
);
create index idx_minor_manual_attendee_event on public.minor_manual_entries (attendee_id, event_id);
create index idx_minor_manual_day_event on public.minor_manual_entries (event_day_id, event_id);
create index idx_minor_manual_added_by on public.minor_manual_entries (added_by);

-- ---------------------------------------------------------------- major_eligibility
-- source 'manual' = + Add Participant (Major); 'import' = historical rows from the
-- removed Major import (kept as history, no longer counted).
create table public.major_eligibility (
  id              integer generated by default as identity primary key,
  event_id        integer not null references public.events (id) on delete restrict on update cascade,
  event_day_id    integer not null,
  attendee_id     integer not null,
  import_batch_id integer references public.import_batches (id) on delete set null on update cascade,
  source          text not null default 'import' check (source in ('import', 'manual')),
  added_by        integer references public.users (id) on delete set null on update cascade,
  reason          varchar(200),
  imported_at     timestamptz not null default now(),
  constraint uq_major_eligibility_day_attendee unique (event_day_id, attendee_id),
  constraint fk_major_eligibility_attendee_event foreign key (attendee_id, event_id)
    references public.attendees (id, event_id) on delete restrict on update cascade,
  constraint fk_major_eligibility_day_event foreign key (event_day_id, event_id)
    references public.event_days (id, event_id) on delete restrict on update cascade
);
create index idx_major_eligibility_attendee_event on public.major_eligibility (attendee_id, event_id);
create index idx_major_eligibility_batch on public.major_eligibility (import_batch_id);
create index idx_major_eligibility_added_by on public.major_eligibility (added_by);
create index idx_major_eligibility_event on public.major_eligibility (event_id);
create index fk_major_eligibility_day_event on public.major_eligibility (event_day_id, event_id);

-- ---------------------------------------------------------------- major_entries (legacy history)
create table public.major_entries (
  id                  integer generated by default as identity primary key,
  event_id            integer not null references public.events (id) on delete restrict on update cascade,
  attendee_id         integer references public.attendees (id) on delete set null on update cascade,
  full_name           varchar(200) not null,
  department          varchar(150),
  email               varchar(190),
  external_identifier varchar(190),
  response_data       jsonb,
  submitted_at        timestamptz,
  import_batch_id     integer references public.import_batches (id) on delete set null on update cascade,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create unique index uq_major_entries_event_external on public.major_entries (event_id, lower(external_identifier));
create index idx_major_entries_event_name on public.major_entries (event_id, full_name);
create index idx_major_entries_event_email on public.major_entries (event_id, email);
create index idx_major_entries_attendee on public.major_entries (attendee_id);
create index idx_major_entries_import_batch on public.major_entries (import_batch_id);

-- ---------------------------------------------------------------- randomizer_draws
-- A draw excludes its winner only while voided_at IS NULL AND reset_at IS NULL.
-- (A partial unique index enforcing "no repeat winner" is deliberately NOT added
-- here: it is randomizer business logic for a later phase, and history from
-- before Phase 9.2 may legitimately contain repeat winners.)
create table public.randomizer_draws (
  id              integer generated by default as identity primary key,
  event_id        integer not null references public.events (id) on delete restrict on update cascade,
  event_day_id    integer not null,
  attendee_id     integer not null references public.attendees (id) on delete restrict on update cascade,
  randomizer_type text not null check (randomizer_type in ('minor', 'major')),
  drawn_by        integer references public.users (id) on delete set null on update cascade,
  selected_at     timestamptz not null default now(),
  voided_at       timestamptz,
  voided_by       integer references public.users (id) on delete set null on update cascade,
  void_reason     varchar(200),
  reset_at        timestamptz,
  reset_by        integer references public.users (id) on delete set null on update cascade,
  constraint fk_randomizer_draws_day_event foreign key (event_day_id, event_id)
    references public.event_days (id, event_id) on delete restrict on update cascade
);
create index idx_randomizer_draws_event_type_time on public.randomizer_draws (event_id, randomizer_type, selected_at);
create index idx_randomizer_draws_attendee on public.randomizer_draws (attendee_id);
create index idx_randomizer_draws_drawn_by on public.randomizer_draws (drawn_by);
create index idx_randomizer_draws_voided_by on public.randomizer_draws (voided_by);
create index idx_randomizer_draws_day_type_time on public.randomizer_draws (event_day_id, randomizer_type, selected_at);
create index fk_randomizer_draws_day_event on public.randomizer_draws (event_day_id, event_id);
create index idx_randomizer_draws_reset_by on public.randomizer_draws (reset_by);

-- ---------------------------------------------------------------- audit_logs
create table public.audit_logs (
  id          bigint generated by default as identity primary key,
  user_id     integer references public.users (id) on delete set null on update cascade,
  event_id    integer references public.events (id) on delete set null on update cascade,
  action      varchar(100) not null,
  description varchar(500),
  metadata    jsonb,
  ip_address  varchar(45),
  user_agent  varchar(255),
  created_at  timestamptz not null default now()
);
create index idx_audit_logs_user on public.audit_logs (user_id);
create index idx_audit_logs_event_time on public.audit_logs (event_id, created_at);
create index idx_audit_logs_action on public.audit_logs (action);
create index idx_audit_logs_created_at on public.audit_logs (created_at);

-- ---------------------------------------------------------------- login_attempts
create table public.login_attempts (
  id           bigint generated by default as identity primary key,
  email_hash   char(64) collate "C" not null,
  ip_address   varchar(45) not null,
  attempted_at timestamptz not null default now()
);
create index idx_login_attempts_email_time on public.login_attempts (email_hash, attempted_at);
create index idx_login_attempts_ip_time on public.login_attempts (ip_address, attempted_at);
create index idx_login_attempts_time on public.login_attempts (attempted_at);

-- ---------------------------------------------------------------- migration_import_runs (new)
-- One row per MySQL -> PostgreSQL import: what was copied and its fingerprints.
create table public.migration_import_runs (
  id                   integer generated by default as identity primary key,
  source_database      text not null,
  source_migrations    jsonb not null,           -- MySQL schema_migrations list at import time
  table_counts         jsonb not null,
  table_fingerprints   jsonb not null,
  qr_fingerprint       text not null,
  qr_identity_fingerprint text not null,
  started_at           timestamptz not null,
  finished_at          timestamptz not null default now()
);

-- ---------------------------------------------------------------- updated_at triggers
create trigger trg_users_updated_at before update on public.users
  for each row execute function public.set_updated_at();
create trigger trg_events_updated_at before update on public.events
  for each row execute function public.set_updated_at();
create trigger trg_event_days_updated_at before update on public.event_days
  for each row execute function public.set_updated_at();
create trigger trg_attendees_updated_at before update on public.attendees
  for each row execute function public.set_updated_at();
create trigger trg_attendee_qr_codes_updated_at before update on public.attendee_qr_codes
  for each row execute function public.set_updated_at();
create trigger trg_major_entries_updated_at before update on public.major_entries
  for each row execute function public.set_updated_at();
